package fleetgql

// Mapping helpers between fleet's internal types (fleet.Role, graph.RoleGraph)
// and the gqlgen-generated GraphQL model. Deliberately NOT in
// schema.resolvers.go: that file is regenerated by `gqlgen generate` and any
// non-resolver code left there gets commented out into a "moved to end"
// warning block on the next regen, silently breaking the build.

import (
	"path"
	"strings"

	"trip2g/cmd/fleet/internal/fleet"
	"trip2g/cmd/fleet/internal/fleet/fleetgql/model"
	"trip2g/cmd/fleet/internal/fleet/graph"
)

// toModelRole projects a parsed fleet.Role onto the GraphQL Role. An empty model
// is null.
func toModelRole(role fleet.Role) model.Role {
	var modelPtr *string
	if role.Model != "" {
		m := role.Model
		modelPtr = &m
	}
	return model.Role{
		Name:           roleName(role.NotePath),
		Path:           role.NotePath,
		Model:          modelPtr,
		TriggerOn:      role.TriggerOn,
		TriggerInclude: role.TriggerInclude,
		TriggerExclude: role.TriggerExclude,
		ReadPatterns:   role.ReadPatterns,
		WritePatterns:  role.WritePatterns,
	}
}

// roleName is the note's base filename without its .md extension.
func roleName(notePath string) string {
	return strings.TrimSuffix(path.Base(notePath), ".md")
}

// toModelRoleGraph maps the derived graph.RoleGraph onto the GraphQL types.
// parseErrors are attached from the caller (DiscoverParsed's per-note errors —
// DeriveRoleGraph itself only ever sees successfully-parsed roles).
func toModelRoleGraph(g graph.RoleGraph, parseErrors []string) *model.RoleGraph {
	nodes := make([]model.GraphNode, 0, len(g.Nodes))
	for _, n := range g.Nodes {
		nodes = append(nodes, model.GraphNode{
			Role:       n.Role,
			InboxGlob:  n.InboxGlob,
			OutboxGlob: n.OutboxGlob,
			Orphan:     n.Orphan,
		})
	}
	edges := make([]model.GraphEdge, 0, len(g.Edges))
	for _, e := range g.Edges {
		edges = append(edges, model.GraphEdge{
			From:       e.From,
			To:         e.To,
			Kind:       model.EdgeKind(e.Kind),
			Exact:      e.Exact,
			CutByDepth: e.CutByDepth,
		})
	}
	return &model.RoleGraph{Nodes: nodes, Edges: edges, Cycles: g.Cycles, ParseErrors: toErrStrings(parseErrors)}
}

// toErrStrings normalizes a nil error-string slice to an empty (non-nil) slice
// so the GraphQL non-null list field never marshals as null.
func toErrStrings(errs []string) []string {
	if errs == nil {
		return []string{}
	}
	return errs
}

// errStrings renders DiscoverParsed's per-note parse errors as strings — the
// debugging surface must show a role that failed to parse, not silently drop
// it from roles/roleGraph.
func errStrings(errs []error) []string {
	if len(errs) == 0 {
		return nil
	}
	out := make([]string, len(errs))
	for i, e := range errs {
		out[i] = e.Error()
	}
	return out
}
